package vn.rtr.aeris.native98;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.BooleanSupplier;
/** Fixed simulator socket. No HTTP, reconnect, retry, persisted grant or endpoint discovery. */
public final class DirectTransport95{
 public interface Sink{void event(String json);}private final File root;private final RawJournal95.Clock clock;private final BooleanSupplier foreground;private final Sink sink;private RawJournal95 journal;private WireGate95 gate;private UnifiedCore98 unified;private String lastPayloadState98="";private Socket socket;private String generation=null,run=null,closedSummary=null;private volatile boolean open=false;private final ArrayDeque<Long> awaiting=new ArrayDeque<>();private int rxBytes=0,txBytes=0;private long openedAt=0;
 public DirectTransport95(File root,RawJournal95.Clock clock,BooleanSupplier foreground,Sink sink){this.root=root;this.clock=clock;this.foreground=foreground;this.sink=sink;}
 private static String quote(String s){return Json.quote(s);}public synchronized boolean isOpen(){return open;}
 public synchronized String open(String run,byte[][]items,String metadata)throws Exception{if(open||generation!=null)throw new IOException("DIRECT_NEW_ACTIVITY_REQUIRED_NO_RECONNECT");if(!foreground.getAsBoolean()||!run.matches("s[a-f0-9]{20}")||items.length<4||items.length>64)throw new IOException("DIRECT_OPEN_CONTEXT");if(!root.isDirectory()&&!root.mkdirs())throw new IOException("DIRECT_STORAGE");File dir=new File(root,run);if(!dir.mkdir())throw new IOException("DIRECT_RUN_ALREADY_EXISTS");generation=UUID.randomUUID().toString();this.run=run;unified=new UnifiedCore98(items,generation);gate=unified.flight;journal=new RawJournal95(new File(dir,"raw.jsonl"),clock);journal.append("META",metadata.getBytes(StandardCharsets.UTF_8));openedAt=clock.now();Socket s=new Socket();socket=s;try{s.connect(new InetSocketAddress("10.0.2.2",5937),3000);s.setTcpNoDelay(true);s.setSoTimeout(500);open=true;journal.append("SOCKET_CONNECTED",("{\"generation\":"+quote(generation)+",\"endpoint\":\"10.0.2.2:5937\"}").getBytes(StandardCharsets.UTF_8));new Thread(()->readLoop(s),"native95-reader").start();return "{\"ok\":true,\"generation\":"+quote(generation)+"}";}catch(Exception e){close("CONNECT_FAILED:"+e.getMessage());throw e;}}
 private void readLoop(Socket s){try{InputStream in=s.getInputStream();byte[]block=new byte[4096];while(open){if(!foreground.getAsBoolean())throw new IOException("NATIVE_BACKGROUND");if(clock.now()-openedAt>900000)throw new IOException("NATIVE_SESSION_DEADLINE");int n;try{n=in.read(block);}catch(SocketTimeoutException e){synchronized(this){unified.tick(clock.now());}continue;}if(n<0)throw new IOException("NATIVE_EOF");if(n==0)continue;byte[]data=Arrays.copyOf(block,n);long at=clock.now(),sequence;String gen; synchronized(this){if(!open)break;sequence=journal.append("RX",data);long applyTime98=clock.now();if(applyTime98-at<0||applyTime98-at>1500)throw new IOException("NATIVE_SHARED_RX_AGE_BOUND");unified.receive(data,applyTime98);String payloadState98=Data97.json(unified.payloadState(applyTime98));if(!payloadState98.equals(lastPayloadState98)){journal.append("PAYLOAD_STATE",payloadState98.getBytes(StandardCharsets.UTF_8));lastPayloadState98=payloadState98;}rxBytes+=data.length;if(awaiting.size()>=64)throw new IOException("NATIVE_RX_BACKPRESSURE_NO_DROP");awaiting.add(sequence);gen=generation;}sink.event("{\"kind\":\"DATA\",\"generation\":"+quote(gen)+",\"receiptMs\":"+at+",\"sequence\":"+sequence+",\"hex\":"+quote(hex(data))+"}");}}catch(Exception e){try{close(e.getMessage());}catch(Exception ignored){}}}
 public synchronized String write(String gen,byte[]data)throws Exception{check(gen);try{byte[]wire=unified.wire(data);journal.append("FLIGHT_INTENT_BINDING",("{\"intentSha256\":"+quote(DraftStore.hash(data))+",\"wireSha256\":"+quote(DraftStore.hash(wire))+"}").getBytes(StandardCharsets.UTF_8));NativeSend98.send((k,b)->journal.append(k,b),b->{socket.getOutputStream().write(b);socket.getOutputStream().flush();},foreground,()->unified.flightApprove(wire,clock.now()),wire);txBytes+=wire.length;return "{\"ok\":true}";}catch(Exception e){close("UNIFIED_FLIGHT_WRITE_UNKNOWN:"+e.getMessage());throw e;}}
 public synchronized String payloadState()throws Exception{if(unified==null)return "{\"ok\":true,\"open\":false,\"phase\":\"CLOSED\",\"generation\":\"\",\"revision\":0,\"stations\":[],\"payloads\":[],\"transactions\":[],\"authorityRestorable\":false,\"unifiedTransport\":true}";Map<String,Object>s=unified.payloadState(clock.now());s.put("ok",true);s.put("run",run);return Data97.json(s);}
 public synchronized PayloadCore97 payloadCore()throws Exception{check(generation);if(!foreground.getAsBoolean())throw new IOException("PAYLOAD_FOREGROUND_REQUIRED");unified.requirePayload();return unified.payload;}
 public synchronized String payloadAttach()throws Exception{check(generation);if(!foreground.getAsBoolean())throw new IOException("PAYLOAD_FOREGROUND_REQUIRED");unified.attach(clock.now());nativeRecord98("PAYLOAD_ATTACH","{\"explicit\":true,\"socketOwner\":\"flight\"}");return payloadState();}
 public synchronized void nativeRecord98(String kind,String data)throws Exception{if(journal==null||!open)throw new IOException("UNIFIED_RAW_CLOSED");try{journal.append(kind,data.getBytes(StandardCharsets.UTF_8));}catch(Exception e){close("UNIFIED_JOURNAL_FAILURE");throw e;}}
 public synchronized String payloadSend(PayloadCore97.Tx t)throws Exception{check(generation);try{byte[]wire=unified.wire(t.bytes);nativeRecord98("PAYLOAD_TX_BINDING",Data97.json(Data97.m("id",t.id,"preparedSha256",DraftStore.hash(t.bytes),"wireSha256",DraftStore.hash(wire),"preparedHex",hex(t.bytes))));final Map<String,Object>[]approval=new Map[1];NativeSend98.send((k,b)->journal.append(k,b),b->{socket.getOutputStream().write(b);socket.getOutputStream().flush();},foreground,()->approval[0]=unified.payloadApprove(t,clock.now()),wire);txBytes+=wire.length;nativeRecord98("PAYLOAD_TX_APPROVAL",Data97.json(approval[0]));return payloadState();}catch(Exception e){close("UNIFIED_PAYLOAD_WRITE_UNKNOWN:"+e.getMessage());throw e;}}
 public synchronized String payloadDetach(String reason)throws Exception{if(unified!=null){unified.detach(reason);if(open)nativeRecord98("PAYLOAD_STATE",payloadState());}return payloadState();}
 public synchronized String payloadHistory()throws Exception{StringBuilder b=new StringBuilder();File[]dirs=root.listFiles();if(dirs==null)dirs=new File[0];if(dirs.length>32)throw new IOException("PAYLOAD_HISTORY_BOUND");for(File d:dirs){if(java.nio.file.Files.isSymbolicLink(d.toPath())||!d.isDirectory())throw new IOException("UNIFIED_HISTORY_PATH");File f=new File(d,"raw.jsonl");if(b.length()>0)b.append(',');b.append("{\"run\":").append(quote(d.getName())).append(",\"bytes\":").append(f.length()).append(",\"authorityRestorable\":false}");}return "{\"ok\":true,\"runs\":["+b+"]}";}
 public synchronized String ack(String gen,long sequence)throws Exception{check(gen);if(awaiting.isEmpty()||awaiting.peek()!=sequence)throw new IOException("NATIVE_RX_ACK_GENERATION_ORDER");awaiting.remove();return "{\"ok\":true}";}
 public synchronized String grant(String gen)throws Exception{check(gen);if(!foreground.getAsBoolean())throw new IOException("NATIVE_FOREGROUND_REQUIRED");gate.grant(clock.now());journal.append("EXPLICIT_GRANT",gate.status(clock.now()).getBytes(StandardCharsets.UTF_8));return "{\"ok\":true}";}
 public synchronized String record(String kind,String data)throws Exception{if(journal==null||!open)throw new IOException("NATIVE_RECORD_SESSION_CLOSED");if(kind.startsWith("PAYLOAD_")||Arrays.asList("META","RX","TX_INTENT","TX_WRITTEN","CLOSED","SOCKET_CONNECTED","EXPLICIT_GRANT","FLIGHT_INTENT_BINDING").contains(kind))throw new IOException("RESERVED_NATIVE_RAW_KIND");journal.append(kind,data.getBytes(StandardCharsets.UTF_8));return "{\"ok\":true}";}
 private void check(String gen)throws IOException{if(!open||!Objects.equals(generation,gen))throw new IOException("NATIVE_GENERATION_OR_CLOSED");}
 public synchronized String close(String reason)throws Exception{if(closedSummary!=null)return closedSummary;if(generation==null)return "{\"ok\":true,\"open\":false}";boolean complete=open&&gate!=null&&gate.safeComplete(clock.now());open=false;if(socket!=null)try{socket.close();}catch(IOException ignored){}if(unified!=null)unified.close(reason);String storageError=null;if(journal!=null){try{journal.append("PAYLOAD_STATE",Data97.json(unified.payloadState(clock.now())).getBytes(StandardCharsets.UTF_8));journal.append("CLOSED",("{\"reason\":"+quote(reason)+",\"safeComplete\":"+complete+",\"authorityRestorable\":false}").getBytes(StandardCharsets.UTF_8));}catch(Exception e){storageError=String.valueOf(e.getMessage());complete=false;}finally{try{journal.close();}catch(Exception e){storageError=String.valueOf(e.getMessage());complete=false;}}}closedSummary="{\"ok\":true,\"open\":false,\"generation\":"+quote(generation)+",\"run\":"+quote(run)+",\"safeComplete\":"+complete+",\"reason\":"+quote(reason)+",\"closureStorageError\":"+quote(storageError)+",\"authorityRestorable\":false,\"rxBytes\":"+rxBytes+",\"txBytes\":"+txBytes+",\"raw\":"+(journal==null?"null":journal.summary())+"}";sink.event("{\"kind\":\"CLOSED\",\"generation\":"+quote(generation)+",\"reason\":"+quote(reason)+"}");return closedSummary;}
 public synchronized String state(){return closedSummary!=null?closedSummary:"{\"ok\":true,\"open\":"+open+",\"generation\":"+quote(generation)+",\"run\":"+quote(run)+",\"rxBytes\":"+rxBytes+",\"txBytes\":"+txBytes+",\"gate\":"+(gate==null?"null":gate.status(clock.now()))+"}";}
 public static byte[]unhex(String s)throws IOException{if(s==null||s.length()>8192||s.length()%2!=0||!s.matches("[a-f0-9]+"))throw new IOException("DIRECT_HEX_BOUND");byte[]b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
 private static String hex(byte[]b){StringBuilder s=new StringBuilder(b.length*2);for(byte x:b)s.append(String.format(java.util.Locale.ROOT,"%02x",x&255));return s.toString();}
}
